import{_ as l,C as a,o as h,c as n,j as t,a as c,E as e,al as r}from"./chunks/framework.D1FqHTxE.js";const C=JSON.parse('{"title":"RadarChart 雷达图","description":"","frontmatter":{},"headers":[],"relativePath":"components/radar-chart.md","filePath":"components/radar-chart.md","lastUpdated":1790578088000}'),s={name:"components/radar-chart.md"},p={id:"radarchart-雷达图",tabindex:"-1"};function b(g,d,u,m,x,R){const i=a("Badge"),o=a("XhDemo");return h(),n("div",null,[t("h1",p,[d[0]||(d[0]=c("RadarChart 雷达图 ",-1)),e(i,{type:"tip",text:"new"}),d[1]||(d[1]=c()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#radarchart-雷达图","aria-label":'Permalink to "RadarChart 雷达图 <Badge type="tip" text="new" />"'},"​",-1))]),d[3]||(d[3]=r('<p>比较少数几个实体在多个指标上的画像。每个指标一根轴，自 12 点方向顺时针排开，一个实体连成一个多边形。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/radar-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/radar-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/radar-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/radar-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/radar-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一行数据一个实体：nameField 取实体名字段，indicators 列出指标；每个指标一根轴，自 12 点顺时针排开</p>',4)),e(o,{src:"radar-chart/01-basic"}),d[4]||(d[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;radar-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <code>legend</code> · <code>legend-item</code> · <code>legend-swatch</code> · <code>legend-label</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>defs</code> · <code>pattern</code> · <code>pattern-line</code> · <code>grid-ring</code> · <code>ring-label</code> · <code>spoke</code> · <code>indicator-label</code> · <code>series</code> · <code>area-fill</code> · <code>line</code> · <code>point</code> · <code>crosshair</code> · <code>focus-ring</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-swatch</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="共用量程" tabindex="-1">共用量程 <a class="header-anchor" href="#共用量程" aria-label="Permalink to &quot;共用量程&quot;">​</a></h3><p>scale=&quot;shared&quot; 让全部指标共用一个量程：单位相同的指标，形状的大小才能跨指标比较</p>',6)),e(o,{src:"radar-chart/02-shared"}),d[5]||(d[5]=t("h3",{id:"指定量程",tabindex:"-1"},[c("指定量程 "),t("a",{class:"header-anchor",href:"#指定量程","aria-label":'Permalink to "指定量程"'},"​")],-1)),d[6]||(d[6]=t("p",null,"指标上写 min / max 固定量程：单位不同的指标各自按自己的尺度读，数据变了轴也不跳",-1)),e(o,{src:"radar-chart/03-range"}),d[7]||(d[7]=t("h3",{id:"圆形网格",tabindex:"-1"},[c("圆形网格 "),t("a",{class:"header-anchor",href:"#圆形网格","aria-label":'Permalink to "圆形网格"'},"​")],-1)),d[8]||(d[8]=t("p",null,'shape="circle" 把网格画成同心圆：指标多、多边形的折角显得杂乱时更安静',-1)),e(o,{src:"radar-chart/04-circle"}),d[9]||(d[9]=t("h3",{id:"只画轮廓",tabindex:"-1"},[c("只画轮廓 "),t("a",{class:"header-anchor",href:"#只画轮廓","aria-label":'Permalink to "只画轮廓"'},"​")],-1)),d[10]||(d[10]=t("p",null,"area 关掉淡洗，只留轮廓线与顶点：实体多、面积叠在一起互相遮挡时更容易分辨",-1)),e(o,{src:"radar-chart/05-outline"}),d[11]||(d[11]=t("h3",{id:"各圈的数值",tabindex:"-1"},[c("各圈的数值 "),t("a",{class:"header-anchor",href:"#各圈的数值","aria-label":'Permalink to "各圈的数值"'},"​")],-1)),d[12]||(d[12]=t("p",null,"ring-labels 在 12 点方向那根轴上写出每一圈的数值，rings 定圈数；只在各指标量程相同时写",-1)),e(o,{src:"radar-chart/06-ring-labels"}),d[13]||(d[13]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>两三个实体在同一组指标上各有长短，读者要看的是整体的「形状」：候选人的能力画像、产品的评测维度、门店的经营指标。</li><li>指标有 3–10 个，且都是「越大越好」或都是「越小越好」，形状的大小才有一致的含义。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>要读出准确的数值或比较几个相近的数：改用<a href="./cartesian-chart">直角坐标图</a>的分组条形图，长度比半径好比较。</li><li>实体多于 3 个：多边形互相遮挡、颜色两两配对也分不清，改成几张小图并排，或者用条形图。</li><li>指标之间有先后或因果关系：轴的次序没有含义，读者会把相邻的指标读成相关的。</li><li>只有一两个指标：围不成面，直接写数字或用条形图。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>数据是对象数组，每行一个实体（一个系列）：<code>nameField</code> 指定实体名所在的字段，<code>indicators</code> 列出指标，每一项写数据里的字段 <code>key</code>、显示的名字 <code>label</code> 与可选的量程 <code>min</code> / <code>max</code>。还没给指标时按空态处理；给了但少于 3 个或多于 10 个时报 <code>chart.indicator-count</code>，字段不存在时报 <code>chart.unknown-field</code>，根上写 <code>data-state=&quot;error&quot;</code>。</li><li>量程由 <code>scale</code> 决定：<code>independent</code>（缺省）每个指标自己的量程，下限缺省 0（有负值时取最小值），上限按全部实体的最大值取整到刻度上；<code>shared</code> 全部指标共用一个量程，适合同一种单位的指标。量程按全部实体算，图例隐藏一个实体时其余实体的形状不变。超出量程的值贴在圆心或最外圈上。</li><li>网格的圈数由 <code>rings</code> 定（2–10，缺省 4），上限按圈数取整到刻度上，每一圈都落在整数刻度。<code>ringLabels</code> 在 12 点方向那根轴的右侧写出每一圈的数值（部件 <code>ring-label</code>）；只在各指标量程相同时写（<code>shared</code>，或各指标写了同样的上下限），量程各不相同时一根轴的刻度代表不了别的轴，写出来反而误读，这时读数交给提示框与数据表。</li><li>网格由 <code>shape</code> 决定：<code>polygon</code>（缺省）画成与指标同数的多边形，<code>circle</code> 画成同心圆；都是等分的四圈加每个指标一根轴，只给眼睛看。指标名写在轴端外侧：右半边从轴端往外写，左半边往回写，正上方与正下方居中；过长时截断。</li><li>每个实体一个分组：轮廓线、铺在里面的系列色淡洗（<code>area</code>，缺省开）与每个指标上的顶点。<code>curve=&quot;catmull-rom&quot;</code> 让轮廓平滑地穿过每个顶点；缺失的值落在圆心、不画顶点，也不进焦点次序。</li><li>颜色按数据次序依次取分类色 1–8；图例隐藏一个实体后，其余实体的颜色不变。多于 3 个实体时开发期报 <code>chart.radar-overlap</code> 提醒（按两两配对检查只有前 3 个色槽都合格），多于 8 个时报错。</li><li>颜色不可用或不可靠时改用纹理区分实体：强制色与打印下总是开启，作者在任意祖先上写 <code>data-xh-chart-patterns</code> 也会开启。淡洗改用本系列的斜线纹理，轮廓换成各自的线型，图例与提示框的色标画成同一副纹理。</li><li>悬停时按角度落到最近的指标轴，那根轴加粗成准线，取这根轴上离指针最近的顶点；提示框列出全部可见实体在这个指标上的值（缺失的写 <code>translations.missingValue</code>），被指着的那一行加粗。其余实体淡出到 <code>--xh-chart-dim-alpha</code>，悬停图例项时同样只保留那个实体。</li><li><code>format</code> 指定数值格式（数字格式或函数），提示框、可及名与数据表共用。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，雷达图按指标的 <code>key</code> 与其他图对齐。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>。首次取数、手里还没有数据时，空态写 <code>translations.loadingText</code> 并转一个圈，取完仍没有数据才写 <code>emptyText</code>。</li><li>首次出现时各实体的轮廓与顶点从圆心一起张开，网格与指标名淡入，数据晚于挂载到达（异步取数，或 Web Components 连上之后才赋 <code>data</code>）时同样播这段入场（空态里已画出的网格留在原处）；之后的数据变化与图例切换从当前形状插值到新形状，隐藏的实体收回并淡出后才移除。<code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡；系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时几何直接到位，只保留淡入淡出。</li><li>过渡的快慢由动效令牌决定：入场取 <code>--xh-motion-duration-reveal</code>，数据更新与图例切换取 <code>--xh-motion-duration-morph</code>，在图或它的容器上改写它们只影响这张图。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、图例、视口与绘图区、空态、提示框），提示框内容可由作用域插槽 / 函数式 children 替换；Web Components 侧作者写外壳（root、caption、legend、viewport 与其中空的 <code>&lt;svg&gt;</code> plot，可选 empty 与 tooltip），网格、系列、图例项与提示框的缺省内容由元素生成进去。</li><li>Web Components 侧的数据、指标与数值格式只走 JS property；实体字段、网格形状、量程、轮廓画法与 <code>active-key</code> 另有同名属性。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，也要说明比较的是什么。</li><li>实体保持在 3 个以内；要比的实体多时，每个实体一张小图，指标次序与量程保持一致。</li><li>把相关的指标排在相邻的位置，读者会把相邻的轴读成一组。</li><li>指标单位不同时用 <code>independent</code>，并在指标名里写出单位或量程；单位相同时用 <code>shared</code>，形状的大小才能跨指标比较。</li><li>需要读出准确数字时，在旁边放一张<a href="./table">表格</a>，或把 <code>api.table</code> 交给表格组件（Vue 与 React 从根的作用域插槽 / 函数式 children 取 <code>table</code>，Web Components 读元素的 <code>table</code>）。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用面积大小比较实体：面积随指标的排列次序而变，换个次序结论就不同。</li><li>把几十个实体叠在一张图上：多边形糊成一团，读者只能靠图例逐个点开。</li><li>混用「越大越好」与「越小越好」的指标：同一个形状的外扩一半是好、一半是坏。</li><li>用提示框作为读取数值的唯一途径：提示框对读屏隐藏，数值要能从摘要或数据表读到。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-radar-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhRadarChartCaption</code> <code>XhRadarChartEmpty</code> <code>XhRadarChartLegend</code> <code>XhRadarChartPlot</code> <code>XhRadarChartRoot</code> <code>XhRadarChartTooltip</code> <code>XhRadarChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>useRadarChart</code></td></tr><tr><td>状态机</td><td><code>radarChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/radar-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>图例切换显隐；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的指标；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个顶点；detail 为数据详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个顶点上；detail 为数据详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRadarChartRoot</code></td><td><code>default</code></td><td><code>RadarChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>tooltip</code></td><td><code>RadarChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhRadarChartTooltip</code></td><td><code>default</code></td><td><code>RadarChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRadarChartRoot</code></td><td><code>data</code></td><td><code>readonly ChartRow[]</code></td><td></td><td>数据：对象数组，每行一个实体（一个系列）。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>nameField</code></td><td><code>string</code></td><td></td><td>实体名所在的字段。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>indicators</code></td><td><code>readonly RadarIndicator[]</code></td><td></td><td>指标：3–10 个，自 12 点方向顺时针排开。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>shape</code></td><td><code>RadarShape</code></td><td></td><td>网格形状，缺省 polygon。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>area</code></td><td><code>boolean</code></td><td></td><td>轮廓里铺一层系列色的淡洗，缺省 true。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>scale</code></td><td><code>RadarScale</code></td><td></td><td>量程，缺省 independent。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>curve</code></td><td><code>RadarCurve</code></td><td></td><td>轮廓的画法，缺省 linear。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>rings</code></td><td><code>number</code></td><td></td><td>网格分几圈，2–10，缺省 4。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>ringLabels</code></td><td><code>boolean</code></td><td></td><td>在 12 点方向那根轴上写出每一圈的数值；只在各指标量程相同时写。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>format</code></td><td><code>NumberFormatSpec | ((value: number) =&gt; string)</code></td><td></td><td>数值格式。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的实体（受控）。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的实体（非受控）。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的键（受控）：与别的图联动时是指标的 key。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;RadarChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>RadarChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>RadarChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>onDatumActive</code></td><td><code>RadarChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>onDatumPress</code></td><td><code>RadarChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: RadarChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhRadarChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;RadarChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhRadarChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;RadarChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的顶点与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>RadarModel</code></td><td>管线产物：系列、量程、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>RadarOverlay</code></td><td>前景层：激活的指标轴与焦点环。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的数据（没有数据、全部隐藏或没有值）。</td></tr><tr><td><code>legendItems</code></td><td><code>readonly RadarLegendItem[]</code></td><td></td></tr><tr><td><code>patterns</code></td><td><code>readonly ChartPattern[]</code></td><td>各系列的纹理：画在绘图区的 defs 里，强制色、打印与环境开启纹理时面积用它填充。</td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的数据；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>RadarTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td></td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：实体名一列，每个指标一列。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td></td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td></td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个系列的显隐。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点：只改锚点，不移动 DOM 焦点，也不派发回调。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; RadarMarkTag</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(item: RadarLegendItem) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLegendSwatchProps</code></td><td><code>(item: RadarLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(item: RadarLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDefsProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>绘图区的第一个子节点：各系列的纹理定义在这里。</td></tr><tr><td><code>getPatternProps</code></td><td><code>(pattern: ChartPattern) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPatternLineProps</code></td><td><code>(pattern: ChartPattern) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: RadarTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipSwatchProps</code></td><td><code>(row: RadarTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: RadarTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: RadarTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点顶点，首次为第一个实体在 12 点方向的指标上；图例同样只占一个 Tab 位</td></tr><tr><td><code>ArrowRight</code></td><td>焦点在绘图区</td><td>顺时针移到同一个实体的下一个指标（跳过缺失值）；已在最后一个则原地不动</td></tr><tr><td><code>ArrowLeft</code></td><td>焦点在绘图区</td><td>逆时针移到上一个指标</td></tr><tr><td><code>ArrowUp</code></td><td>焦点在绘图区</td><td>在同一个指标上换到图例次序的下一个实体，跳过隐藏的实体与缺失值</td></tr><tr><td><code>ArrowDown</code></td><td>焦点在绘图区</td><td>在同一个指标上换到上一个实体</td></tr><tr><td><code>Home</code> / <code>PageUp</code></td><td>焦点在绘图区</td><td>同一个实体的第一个指标</td></tr><tr><td><code>End</code> / <code>PageDown</code></td><td>焦点在绘图区</td><td>同一个实体的最后一个指标</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的顶点（onDatumPress）</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>焦点在图例</td><td>在图例项之间移动，左右键跟随文字方向的视觉次序</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在图例项</td><td>切换该实体的显隐（原生按钮行为）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-pressed</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-label</code></td><td>undefined | s?.name</td></tr><tr><td><code>mark</code></td><td><code>aria-roledescription</code></td><td>undefined | translations.seriesRoleDescription</td></tr><tr><td><code>mark</code></td><td><code>role</code></td><td>undefined | &#39;graphics-object&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>；不放标题时在根上写 <code>aria-label</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-describedby</code> 指向组件生成的摘要；每个实体是一个 <code>role=&quot;graphics-object&quot;</code> 的分组，名称是实体名；每个顶点是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省「指标, 实体 值」），务必按本地语言改写。</li><li>绘图区只占一个 Tab 位，焦点落在顶点上：左右键沿顺时针在同一个实体的指标之间走，上下键在同一个指标上换实体，Home / End 到第一个与最后一个指标。焦点环画在顶点之外，只在键盘聚焦时出现。</li><li>网格、指标轴、指标名、准线与焦点环一律 <code>aria-hidden</code>；提示框同样 <code>aria-hidden</code>：它显示的内容与顶点的名称是同一份。</li><li>组件在根内生成一段摘要与一张数据表，视觉隐藏、对读屏可见：摘要写实体数、指标数，以及每个实体最高与最低的指标（按在各自量程里的位置比，模板是 <code>translations.summary</code>）；数据表首列是实体名（列名取 <code>translations.nameLabel</code>），其余每个指标一列。</li><li>图例是 <code>role=&quot;toolbar&quot;</code>，每一项是 <code>&lt;button aria-pressed&gt;</code>，按下表示实体可见；图例整体只占一个 Tab 位。</li><li>颜色不是区分实体的唯一线索：图例与提示框写出实体名，顶点的名称也带着实体名；强制色与打印下还有各自的纹理与线型。</li><li>过渡只改画面：顶点的名称、摘要与数据表在数据变化的那一刻就按新数据更新；收场中的实体 <code>aria-hidden</code>、不可聚焦。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/radar-chart.css</code> 使用 <code>[data-scope=&quot;radar-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>legend</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend-item</code></td><td><code>data-value</code></td><td>item.id</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-item&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-pattern</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-slot</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-swatch&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>defs</code></td><td><code>data-xh-chart-part</code></td><td>&#39;defs&#39;</td></tr><tr><td><code>pattern</code></td><td><code>data-xh-chart-part</code></td><td>&#39;pattern&#39;</td></tr><tr><td><code>pattern</code></td><td><code>data-xh-chart-slot</code></td><td>undefined | String(pattern.slot)</td></tr><tr><td><code>pattern-line</code></td><td><code>data-xh-chart-part</code></td><td>&#39;pattern-line&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-series-id</code></td><td>row.seriesId</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-pattern</code></td><td>String(row.slot)</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-slot</code></td><td>String(row.slot)</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-swatch&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-xh-loading-ring</code></td><td>&#39;&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-series-id</code></td><td>mark.key.slice(&#39;series:&#39;.length)</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-slot</code></td><td>String(s.slot) | undefined | String(mark.paint.slot)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-radar-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>radar-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>radar-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>radar-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-legend-gap</code></td><td><code>legend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>radar-chart 的 legend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-legend-swatch-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>radar-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-line-width</code></td><td><code>legend-swatch</code><br><code>line</code><br><code>root</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>block-size</code><br><code>stroke-dasharray</code><br><code>stroke-width</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>default</code><br><code>mark=line</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code></td><td><code>--xh-chart-line-width</code></td><td>radar-chart 的 legend-swatch、line、root、tooltip-swatch 部件 background、block-size、stroke-dasharray、stroke-width 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-point-size</code></td><td><code>legend-swatch</code><br><code>root</code><br><code>tooltip-swatch</code></td><td><code>background</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=1</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code></td><td><code>--xh-chart-point-size</code></td><td>radar-chart 的 legend-swatch、root、tooltip-swatch 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-ring-label-fg</code></td><td><code>ring-label</code></td><td><code>fill</code></td><td><code>default</code></td><td><code>--xh-chart-label</code></td><td>radar-chart 的 ring-label 部件 fill 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-ring-label-opacity</code></td><td><code>ring-label</code></td><td><code>opacity</code></td><td><code>default</code></td><td><code>0.8</code></td><td>radar-chart 的 ring-label 部件 opacity 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-series-color</code></td><td><code>area-fill</code><br><code>legend-swatch</code><br><code>line</code><br><code>pattern-line</code><br><code>point</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>border</code><br><code>fill</code><br><code>stroke</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>mark=line</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=1</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code><br><code>xh-chart-slot=1</code><br><code>xh-chart-slot=2</code><br><code>xh-chart-slot=3</code><br><code>xh-chart-slot=4</code><br><code>xh-chart-slot=5</code><br><code>xh-chart-slot=6</code><br><code>xh-chart-slot=7</code><br><code>xh-chart-slot=8</code></td><td><code>--xh-chart-categorical-1</code><br><code>--xh-chart-categorical-2</code><br><code>--xh-chart-categorical-3</code><br><code>--xh-chart-categorical-4</code><br><code>--xh-chart-categorical-5</code><br><code>--xh-chart-categorical-6</code><br><code>--xh-chart-categorical-7</code><br><code>--xh-chart-categorical-8</code></td><td>radar-chart 的 area-fill、legend-swatch、line、pattern-line、point、tooltip-swatch 部件 background、border、fill、stroke 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>radar-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>radar-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>radar-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>radar-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>radar-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>radar-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-radar-chart-tooltip-swatch-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>radar-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：状态 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-fade-in</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：指标自 12 点顺时针排列，右键始终是顺时针的下一个指标。</li><li>图例、标题与提示框的内容随文字方向排列，图例的左右键跟随视觉次序翻转。</li></ul>',56))])}const k=l(s,[["render",b]]);export{C as __pageData,k as default};
